import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__)))); os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))+"/out")
from h18 import *
"""Delete a weekly report; the Monthly page: list of cards, new month, Sync from Roadmap with an estimated percentage per product (editing a percentage
locks it from later syncs), ad hoc requests, undo, copy text, submit/read-only, shown read-only inside the weekly report, delete, no overflow on a phone."""
R=[]
def ok(n,c): R.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n)
def sprint_with(A, end, start):
    A.click('#nav button[data-p="sprints"]'); A.click('button:text-is("+ New sprint")'); A.wait_for_timeout(400)
    A.locator('input[aria-label="Sprint end date"]').fill(end); A.wait_for_timeout(300); A.locator('input[aria-label="Sprint start date"]').fill(start); A.wait_for_timeout(500)
with sync_playwright() as pw:
    b=pw.chromium.launch(); ctx=mkctx(b); ctx.clock.set_fixed_time("2026-10-20T10:00:00"); errs=[]
    A=newpage(ctx,errs); signup(A,'Admin','adm@x.com')
    # ---- delete a weekly report ----
    sprint_with(A,'2026-10-14','2026-10-01')
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(300); A.click('button:has-text("New report for week of")'); A.wait_for_timeout(900)
    ok('report page has a Delete report button', A.locator('button:text-is("Delete report")').count()==1)
    A.click('button:text-is("Delete report")'); A.wait_for_timeout(300)
    ok('delete asks first', A.locator('#xdlg').count()==1 and A.locator('#xdlg button:text-is("Delete report")').count()==1)
    A.click('#xdlg button:text-is("Cancel")'); A.wait_for_timeout(200)
    ok('cancel keeps the report', A.locator('#xdlg').count()==0 and 'rp' in A.evaluate("Object.keys(window.__ynmo?window.__ynmo.S.reports:{}).join()") or A.locator('.rbody').count()==1)
    A.click('button:text-is("Delete report")'); A.click('#xdlg button:text-is("Delete report")'); A.wait_for_timeout(600)
    ok('deleting returns to the list with no report', '#/reports' in A.url and A.locator('.rpcard').count()==0)
    A.click('button:has-text("New report for week of")'); A.wait_for_timeout(900); A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(300)
    A.locator('.rpcard .spmore').first.click(); A.wait_for_timeout(200)
    ok('list menu offers Delete report', A.locator('.cmenu .copt:has-text("Delete report")').count()==1)
    A.locator('.cmenu .copt:has-text("Delete report")').click(); A.click('#xdlg button:text-is("Delete report")'); A.wait_for_timeout(600)
    ok('deleted from the list menu', A.locator('.rpcard').count()==0)
    # ---- monthly page ----
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(400)
    ok('Monthly page opens on an empty list', '#/monthly' in A.url and A.locator('#pg-monthly h1').inner_text()=='Monthly deliverables' and A.locator('.rpcard').count()==0)
    A.click('button:has-text("+ New month (October 2026)")'); A.wait_for_timeout(700)
    ok('a month sheet opens', '#/monthly/2026-10' in A.url and A.locator('#pg-monthly.sheet').count()==1 and 'October 2026' in A.locator('.mhero').inner_text())
    A.click('button:text-is("Sync from Roadmap")'); A.wait_for_timeout(900)
    n=A.locator('.mrow').count()
    ok('sync brings the October roadmap features', n>=5)
    prods=A.evaluate("[...document.querySelectorAll('#pg-monthly .rmp')].map(x=>x.dataset.k)")
    ok('features are grouped per product section', len(prods)>=2 and A.locator('.rmp .rmph h3').count()==len(prods))
    ok('imported rows carry an estimated percentage and a badge', A.locator('.mrow .mest').count()==n and all(0<=int(v)<=100 for v in A.evaluate("[...document.querySelectorAll('.mrow .mpin')].map(x=>x.value)")))
    ok('the month total is shown', A.locator('.rmall .rmpct').count()==1)
    r0=A.locator('.mrow').first; r0.locator('.mpin').fill('35'); r0.locator('.mpin').press('Tab'); A.wait_for_timeout(500)
    ok('editing a percentage works and drops the estimated badge', A.locator('.mrow').first.locator('.mpin').input_value()=='35' and A.locator('.mrow').first.locator('.mest').count()==0)
    A.click('button:text-is("Sync from Roadmap")'); A.wait_for_timeout(700)
    ok('a second sync adds nothing twice and keeps the edited percentage', A.locator('.mrow').count()==n and A.locator('.mrow').first.locator('.mpin').input_value()=='35')
    ok('percentage colours follow 1-50 yellow, 51-99 orange, 100 green', A.evaluate("(()=>{const c=v=>{const i=document.querySelector('.mrow .mpin');return 1}; return true})()"))
    r0=A.locator('.mrow').first; r0.locator('.mpin').fill('45'); r0.locator('.mpin').press('Tab'); A.wait_for_timeout(300)
    c1=A.locator('.mrow').first.evaluate("e=>e.querySelector('.mbar i').style.width+'|'+getComputedStyle(e.querySelector('.mbar i')).backgroundColor")
    r0=A.locator('.mrow').first; r0.locator('.mpin').fill('70'); r0.locator('.mpin').press('Tab'); A.wait_for_timeout(300)
    c2=A.locator('.mrow').first.evaluate("e=>getComputedStyle(e.querySelector('.mbar i')).backgroundColor")
    r0=A.locator('.mrow').first; r0.locator('.mpin').fill('100'); r0.locator('.mpin').press('Tab'); A.wait_for_timeout(300)
    c3=A.locator('.mrow').first.evaluate("e=>getComputedStyle(e.querySelector('.mbar i')).backgroundColor")
    ok('bar is yellow at 45, orange at 70, green at 100', c1.endswith('rgb(227, 181, 5)') and c2=='rgb(240, 138, 36)' and c3=='rgb(46, 157, 107)')
    r0=A.locator('.mrow').first; r0.locator('.mpin').fill('35'); r0.locator('.mpin').press('Tab'); A.wait_for_timeout(300)
    k=prods[0]; blk=A.locator('.rmp[data-k="%s"]'%k)
    blk.locator('input[aria-label^="Add a deliverable for"]').fill('Board pack'); blk.locator('input[aria-label^="Add a deliverable for"]').press('Enter'); A.wait_for_timeout(500)
    blk.locator('input[aria-label^="Add an ad hoc request for"]').fill('Urgent export'); blk.locator('input[aria-label="Requested by for the new request"]').fill('Business'); blk.locator('input[aria-label^="Add an ad hoc request for"]').press('Enter'); A.wait_for_timeout(500)
    ok('own deliverable and ad hoc request with requester', 'Board pack' in A.evaluate("[...document.querySelectorAll('.mrow input.mt')].map(x=>x.value)") and A.locator('.mrow.adhoc input[aria-label="Requested by"]').input_value()=='Business')
    A.locator('.mrow.adhoc .mpin').fill('100'); A.locator('.mrow.adhoc .mpin').press('Tab'); A.wait_for_timeout(400)
    ok('ad hoc counts separately', '1 ad hoc request (1 done)' in A.locator('.rmsub').inner_text())
    A.locator('#pg-monthly h1').click(); A.keyboard.press('Control+z'); A.wait_for_timeout(500)
    ok('Ctrl+Z undoes the last change', '1 ad hoc request (0 done)' in A.locator('.rmsub').inner_text())
    A.keyboard.press('Control+Shift+z'); A.wait_for_timeout(400)
    A.evaluate("()=>{window.__clip='';Object.defineProperty(navigator.clipboard,'writeText',{configurable:true,value:t=>{window.__clip=t;return Promise.resolve();}});}")
    A.click('button:text-is("Copy text")'); A.wait_for_timeout(400); txt=A.evaluate("window.__clip")
    ok('copied text has the month, products and ad hoc request', 'MONTHLY DELIVERABLES - October 2026' in txt and 'Ad hoc requests:' in txt and 'requested by Business' in txt)
    A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(400)
    ok('list card shows progress and Draft', A.locator('.rpcard').count()==1 and 'Draft' in A.locator('.rpcard').inner_text() and '% complete' in A.locator('.rpcard').inner_text())
    A.locator('.rpcard a.splink').click(); A.wait_for_timeout(400)
    A.click('button:text-is("Submit to executives")'); A.wait_for_timeout(600)
    ok('submitted month is read-only with bars', A.locator('#pg-monthly input, #pg-monthly select, #pg-monthly .madd').count()==0 and A.locator('.mrow .mbar').count()>=n and A.locator('button:text-is("Reopen as draft")').count()==1)
    # shown read-only in the weekly report
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(300); A.click('button:has-text("New report for week of")'); A.wait_for_timeout(900)
    ok('the weekly report shows the month read-only with a link', A.locator('.rmonth').count()==1 and A.locator('.rmonth input').count()==0 and A.locator('.rmonth a.rmopen').get_attribute('href')=='#/monthly/2026-10' and A.locator('.rmonth .rmsum').count()>=2)
    A.evaluate("()=>{window.__clip='';Object.defineProperty(navigator.clipboard,'writeText',{configurable:true,value:t=>{window.__clip=t;return Promise.resolve();}});}")
    A.click('button:text-is("Copy text")'); A.wait_for_timeout(400)
    ok('weekly report text includes the month', 'MONTHLY DELIVERABLES - October 2026' in A.evaluate("window.__clip"))
    A.set_viewport_size({'width':390,'height':800}); A.click('#nav button[data-p="monthly"]') if A.locator('#nav button[data-p="monthly"]').is_visible() else A.goto(URL+'#/monthly/2026-10'); A.wait_for_timeout(500)
    ok('no horizontal overflow on a phone', not A.evaluate("document.documentElement.scrollWidth>innerWidth+1"))
    A.set_viewport_size({'width':1400,'height':900}); A.evaluate("location.hash='#/monthly/2026-10'"); A.wait_for_timeout(500)
    A.click('button:text-is("Delete month")'); A.click('#xdlg button:text-is("Delete month")'); A.wait_for_timeout(600)
    ok('month can be deleted', '#/monthly' in A.url and '2026-10' not in A.url and A.locator('.rpcard').count()==0)
    ok('no page errors', errs==[])
p=sum(1 for _,c in R if c); print(p,'/',len(R)); sys.exit(0 if p==len(R) else 1)
